using Capsule.Core;
GlassMaterialTests.Run();
var now = DateTimeOffset.UtcNow;
var solo=new SoloState();
if(!solo.Apply("{\"type\":\"init\",\"lyrics\":[{\"time\":1000,\"text\":\"Test\",\"translation\":\"译文\"}]}",0) || solo.Lyrics.Lines.Count!=1)throw new Exception("Solo lyric protocol failed");
solo.Apply("{\"type\":\"progress\",\"position\":1000}",100);solo.Apply("{\"type\":\"playback\",\"status\":\"playing\"}",100);solo.Apply("{\"type\":\"playback\",\"status\":\"paused\"}",600);
if(solo.Position(5000)!=1500 || solo.Apply("{broken",0))throw new Exception("Solo pause or malformed-message handling failed");
Console.WriteLine("PASS Solo lyrics, progress extrapolation, pause and malformed-message isolation");
var mergedSolo=new SoloState();mergedSolo.Apply("{\"type\":\"init\",\"lyrics\":[7,{\"time\":\"bad\",\"text\":\"ignored\"},{\"time\":1000,\"text\":\"Original\\n译文\"},{\"time\":2000,\"text\":\"Second\\u2028自动译文\",\"translation\":\"显式译文\"}]}",0);
if(mergedSolo.Lyrics.Lines.Count!=2 || mergedSolo.Lyrics.Lines[0].Text!="Original" || mergedSolo.Lyrics.Lines[0].Translation!="译文" || mergedSolo.Lyrics.Lines[1].Translation!="显式译文")throw new Exception("Solo merged translation or invalid row isolation failed");
if(mergedSolo.Apply("{\"type\":\"progress\",\"position\":1e300}",0))throw new Exception("Huge Solo progress was accepted");
mergedSolo.Apply("{\"type\":\"progress\",\"position\":2147483647}",0);mergedSolo.Apply("{\"type\":\"playback\",\"status\":\"playing\"}",0);
if(mergedSolo.Position(long.MaxValue)!=int.MaxValue)throw new Exception("Solo extrapolation escaped the protocol time range");
mergedSolo.Apply("{\"type\":\"init\"}",0);if(mergedSolo.Lyrics.Lines.Count!=0)throw new Exception("Invalid replacement init retained previous track lyrics");
Console.WriteLine("PASS Solo merged translations, invalid row isolation, bounded time extrapolation and invalid-init cleanup");
var s = new IslandState();
void Check(bool ok, string message) { if (!ok) throw new Exception(message); Console.WriteLine("PASS " + message); }
foreach(var item in new[]{(Dpi:96u,X:-1110,Y:-192),(Dpi:120u,X:-1148,Y:-190),(Dpi:144u,X:-1185,Y:-188),(Dpi:192u,X:-1260,Y:-184)})
{
    var point=MonitorGeometry.Center(new(-1920,-200,1920,1080),(int)(300*item.Dpi/96), (int)(35*item.Dpi/96),item.Dpi,8);
    Check(point==new PixelPoint(item.X,item.Y),"Negative-origin monitor placement at DPI "+item.Dpi);
}
Check(MonitorGeometry.WidthLimit(320,192)==144 && MonitorGeometry.WidthLimit(320,0)==304,"Narrow monitor uses its own logical width and zero DPI falls back to 96");
Check(MonitorGeometry.Center(new(-800,-400,800,600),1000,900,192,80)==new PixelPoint(-800,-400),"Oversized window anchors inside work-area origin without negative inset");
var supplementBase=LyricsDocument.Parse("[00:01.00]First line\n[00:03.00]Second line",source:"Base");
var supplementOther=LyricsDocument.Parse("[00:01.10]First line\n[00:03.10]Second line","[00:01.10]第一句\n[00:03.10]第二句","[1100,1500](1100,1500,0)First line\n[3100,1500](3100,1500,0)Second line","Extra");
var supplemented=supplementBase.Supplement(supplementOther);
Check(supplemented.HasWordTiming && supplemented.Lines[0].Translation=="第一句" && supplemented.Lines[0].StartMs==1000 && supplemented.Lines[0].Text=="First line","Cross-source supplement preserves base text/timing and adds matched translation/words");
Check(ReferenceEquals(supplementBase,supplementBase.Supplement(LyricsDocument.Parse("[00:02.00]First line\n[00:04.00]Second line","[00:02.00]错版"))) && ReferenceEquals(supplementBase,supplementBase.Supplement(LyricsDocument.Parse("[00:01.00]First line\n[00:03.00]Different line","[00:01.00]错版"))),"Shifted recording and insufficient shared text cannot supplement lyrics");
Check(ReferenceEquals(supplemented,supplemented.Supplement(supplementOther)),"Supplement preserves existing translation and timing without repeated source tags");
Check(ComponentOrder.Normalize(null,hardwareFirst:true,mediaFirst:true).SequenceEqual(new[]{"media","hardware","clock"}),"Legacy component order migrates without losing media/hardware placement");
Check(ComponentOrder.Normalize(new[]{"bad","plugin:fixture.clock","plugin:fixture.clock","media"}).SequenceEqual(new[]{"plugin:fixture.clock","media","clock","hardware"}),"Unified order removes invalid/duplicate IDs and restores native slots");
Check(ComponentOrder.Effective(new[]{"plugin:stopped.clock","hardware","media","clock"},new[]{"fixture.clock"}).SequenceEqual(new[]{"plugin:stopped.clock","hardware","media","clock","plugin:fixture.clock"}),"Inactive plugin positions survive while new components append");
var overflowingTime=new string('9',400);
Check(LyricsDocument.Parse("["+overflowingTime+":00]Test").Lines.Count==0 && LyricsDocument.Parse("[offset:"+overflowingTime+"]\n[00:01.00]Test").Lines.Count==0,"Non-finite lyric timestamps and offsets are rejected");
Check(!LyricsDocument.Parse("[00:01.00]Test",wordTiming:"[1000,2000](1000,"+overflowingTime+",0)Test").HasWordTiming,"Non-finite word durations fall back to normal lyric timing");
Check(MediaSessionPolicy.Matches("LX-Music-Desktop.exe","lxmusic") && MediaSessionPolicy.Matches("Microsoft.MicrosoftEdge.Stable!App","browser") && !MediaSessionPolicy.Matches("qqmusic.exe","netease") && MediaSessionPolicy.Matches("QQMusic.exe","other","qqmusic.EXE"),"Media source aliases and explicit source selection are preserved");
var validity=new StaleMediaSessions();
Check(MediaTitlePolicy.Select("bilibili.test","Old title",new(false,"New title"))=="New title" && MediaTitlePolicy.Select("other.exe","Old title",new(false,"New title"))=="Old title","Only tracked media can use an unambiguous visible-window title");
Check(MediaTitlePolicy.Select("bilibili.test","Old title",new(true,"New title"))=="Old title" && MediaTitlePolicy.Select("bilibili.test","Old title",new(null,"New title"))=="Old title" && MediaTitlePolicy.Select("bilibili.test","Old title",new(false,"哔哩哔哩"))=="Old title","Corroborated, unknown and app-main-window evidence cannot override media title");
Check(!validity.IsStale("bilibili.test","Owned title",false,false,0) && !validity.IsStale("bilibili.test","Owned title",false,false,100) && validity.IsStale("bilibili.test","Owned title",false,false,250),"Tracked stale media requires two separated missing-window observations");
Check(!validity.IsStale("bilibili.test","Owned title",true,false,300) && !validity.IsStale("bilibili.test","Owned title",false,null,400) && !validity.IsStale("qqmusic","Owned title",false,false,1000),"Playing, unknown evidence and untracked apps cannot be discarded as stale");
Check(s.Mode == IslandMode.Clock, "Initial clock");
s.UpdateMedia(new("A", "Artist", true, true));
s.Show(new("app", "App", "Title", "Body"), now);
s.UpdateMedia(new("B", "Artist", true, true));
Check(s.Mode == IslandMode.Notification, "Notification retains priority during track change");
s.Tick(now.AddSeconds(7));
Check(s.Mode == IslandMode.Media && s.Media.Title == "B", "Resume latest track, not old frame");
s.Show(new("app", "App", "Title", "Body"), now);
s.UpdateMedia(new("B", "Artist", false, true)); s.Dismiss();
Check(s.Mode == IslandMode.Clock && s.Media.Available, "Pause during notification returns clock with controls available");
s.Show(new("app", "App", "Title", "Body"), now); s.Expand(now.AddSeconds(5)); s.Tick(now.AddSeconds(7));
Check(s.Notification is not null && s.Expanded, "Expanded notice has extended deadline");
s.UpdateMedia(new("", "", false, false)); s.Tick(now.AddSeconds(26));
Check(s.Mode == IslandMode.Clock && !s.Media.Available, "Player exit and notification timeout");
s.Show(new("a", "A", "1", ""), now); s.Show(new("b", "B", "2", ""), now.AddSeconds(3)); s.Tick(now.AddSeconds(7));
Check(s.Notification?.App == "B" && !s.Expanded, "New notification replaces old one with fresh timeout");
s.Tick(now.AddDays(1)); Check(s.Mode == IslandMode.Clock, "Wake after expiration");

var lyrics=LyricsDocument.Parse("[00:01.00]Alpha\n[00:03.50][00:05.00]Beta","[00:01.00]One\n[00:03.50]Two");
Check(lyrics.Lines.Count==3 && lyrics.At(TimeSpan.FromMilliseconds(900)).Line is null,"LRC multiple time tags and initial silence");
Check(lyrics.At(TimeSpan.FromMilliseconds(1500)).Line?.Translation=="One","Translation matched by time");
Check(Math.Abs(lyrics.At(TimeSpan.FromMilliseconds(2250)).Progress-0.5)<0.001,"Line progress is based on playback time");
Check(lyrics.At(TimeSpan.FromMilliseconds(900),0.2).Line?.Text=="Alpha","User lyric offset advances line selection");
var words=LyricsDocument.Parse("[00:01.00]Alpha Beta",wordTiming:"[1000,2000](1000,1000,0)Alpha (2000,1000,0)Beta");
Check(words.HasWordTiming && words.Lines[0].Words.Count==2,"Time-before-text YRC parsed");
var suffix=LyricsDocument.Parse("[00:01.00]AlphaBeta",wordTiming:"[1000,2000]Alpha(1000,1000)Beta(2000,1000)");
Check(suffix.HasWordTiming && suffix.Lines[0].Words[1].StartMs==2000,"Text-before-time word timing parsed");
var mismatch=LyricsDocument.Parse("[00:01.00]Original",wordTiming:"[1000,2000](1000,1000,0)Wrong");
Check(!mismatch.HasWordTiming,"Different lyric version does not acquire incorrect word timing");
s.MediaClockSwitch=false;s.UpdateMedia(new("Paused","Artist",false,true));Check(s.Mode==IslandMode.Media,"Disabling media-clock switch retains paused media");
s.MediaClockSwitch=true;Check(s.Mode==IslandMode.Clock,"Re-enabling media-clock switch returns paused clock");

s.Dismiss();s.Show(new("app","App","First","",1),now);s.Expand(now.AddSeconds(1));s.Show(new("APP","App","Latest","",2),now.AddSeconds(2));
Check(s.GroupCount==2 && s.LastNoticeGrouped && s.Notification?.Title=="Latest" && !s.Expanded,"Distinct same-source notices merge and reset reader to latest content");
s.Show(new("app","App","Updated","",2),now.AddSeconds(3));Check(s.GroupCount==1 && !s.LastNoticeGrouped,"Updating the same notification ID does not increment group count");
s.Show(new("other","Other","Other","",3),now.AddSeconds(4));Check(s.GroupCount==1 && !s.LastNoticeGrouped,"Different sources do not merge");
s.Show(new("other","Other","After expiry","",4),now.AddSeconds(11));Check(s.GroupCount==1 && !s.LastNoticeGrouped,"Expired notice does not merge into new notification");
s.GroupNotifications=false;s.Show(new("other","Other","Ungrouped","",5),now.AddSeconds(12));Check(s.GroupCount==1 && !s.LastNoticeGrouped,"Grouping preference is respected");
s.SetQuietUntil(now.AddMinutes(30),now.AddSeconds(13));Check(s.Notification==null && !s.Show(new("app","App","Muted","",6),now.AddMinutes(1)),"Quiet period dismisses overlay and rejects incoming notices");
s.Tick(now.AddMinutes(31));Check(s.Notification==null && !s.IsQuiet(now.AddMinutes(31)),"Quiet expiry does not replay muted notices");
Check(s.Show(new("app","App","New","",7),now.AddMinutes(31)) && s.GroupCount==1,"New notices resume after quiet expiry");

Check(Enum.GetValues<ShortcutAction>().All(action=>ShortcutChord.Default(action).IsValid) && new ShortcutChord(0,0).IsValid,"Default and cleared shortcut chords are valid");
Check(!new ShortcutChord(0,65).IsValid && !new ShortcutChord(2,17).IsValid && !new ShortcutChord(16,65).IsValid,"Bare keys, modifier-only chords and unknown modifier flags are rejected");
var visibility=default(IslandVisibilityInput) with{AutoHide=true,FocusHide=true};
Check(IslandVisibility.Resolve(visibility).Hidden && IslandVisibility.Resolve(visibility).ShowWake,"Idle auto-hide retains wake entry");
Check(!IslandVisibility.Resolve(visibility with{AutoHide=false}).Hidden,"Auto-hide master switch controls idle rule");
Check(!IslandVisibility.Resolve(visibility with{MediaAvailable=true,Playing=true}).Hidden,"Playing media overrides idle rule");
Check(IslandVisibility.Resolve(visibility with{MediaAvailable=true,PauseHide=true}).Hidden,"Paused media hides when pause rule is enabled");
Check(IslandVisibility.Resolve(visibility with{MediaAvailable=true,Playing=true,FullscreenHide=true,Fullscreen=true}).Hidden,"Fullscreen rule also hides playing media");
Check(!IslandVisibility.Resolve(visibility with{Notification=true}).Hidden && !IslandVisibility.Resolve(visibility with{Expanded=true}).Hidden && !IslandVisibility.Resolve(visibility with{Awake=true}).Hidden,"Notifications, expanded panels and explicit wake protect automatic visibility");
Check(IslandVisibility.Resolve(visibility with{ManualHidden=true,Notification=true,Expanded=true,Awake=true}) is{Hidden:true,ShowWake:false,PassThrough:true},"Manual hide removes all island UI including wake button");
Check(IslandVisibility.Resolve(default(IslandVisibilityInput) with{Passthrough=true,PointerOver=true}) is{Hidden:false,ShowWake:true,PassThrough:true},"Hover passthrough exposes wake entry");
Check(!IslandVisibility.Resolve(default(IslandVisibilityInput) with{Passthrough=true,PointerOver=true,Notification=true}).PassThrough,"Notification remains interactive in passthrough mode");
